package pipedrive

import (
	"context"
	"errors"
	"io"
	"math"
	rand "math/rand/v2"
	"net/http"
	"time"
)

type RetryPolicy struct {
	MaxAttempts int
	BaseDelay   time.Duration
	MaxDelay    time.Duration

	// MaxRetryAfter caps how long a server-provided Retry-After header may
	// delay a retry, so a misbehaving server cannot pin the client
	// indefinitely. Zero uses the 1 minute default; negative disables the
	// cap.
	MaxRetryAfter time.Duration

	Jitter func(time.Duration) time.Duration

	RetryAllMethods bool
}

const defaultMaxRetryAfter = time.Minute

func DefaultRetryPolicy() RetryPolicy {
	return RetryPolicy{
		MaxAttempts:     4,
		BaseDelay:       200 * time.Millisecond,
		MaxDelay:        5 * time.Second,
		MaxRetryAfter:   defaultMaxRetryAfter,
		Jitter:          fullJitter,
		RetryAllMethods: false,
	}
}

type retryTransport struct {
	next   http.RoundTripper
	policy RetryPolicy
	opts   retryTransportOptions
}

type retryTransportOptions struct {
	sleep func(context.Context, time.Duration) error
	now   func() time.Time
}

func newRetryTransport(next http.RoundTripper, policy RetryPolicy, opts retryTransportOptions) http.RoundTripper {
	if next == nil {
		next = http.DefaultTransport
	}
	policy = sanitizeRetryPolicy(policy)
	if opts.sleep == nil {
		opts.sleep = sleepWithContext
	}
	if opts.now == nil {
		opts.now = time.Now
	}
	return &retryTransport{
		next:   next,
		policy: policy,
		opts:   opts,
	}
}

func (t *retryTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	if req == nil {
		return nil, errors.New("pipedrive: nil request")
	}

	policy := t.policy
	if override, ok := retryPolicyFromContext(req.Context()); ok {
		policy = sanitizeRetryPolicy(override)
	}

	if isNoRetry(req.Context()) || policy.MaxAttempts <= 1 {
		return t.next.RoundTrip(req)
	}

	origGetBody := req.GetBody
	canReplayBody := req.Body == nil || req.Body == http.NoBody || origGetBody != nil

	for attempt := 1; ; attempt++ {
		attemptReq := req
		if attempt > 1 {
			attemptReq = req.Clone(req.Context())
			if origGetBody != nil {
				body, err := origGetBody()
				if err != nil {
					return nil, err
				}
				attemptReq.Body = body
			}
		}

		resp, err := t.next.RoundTrip(attemptReq)
		if !t.shouldRetry(attempt, attemptReq, canReplayBody, resp, err, policy) {
			return resp, err
		}

		delay := t.nextDelay(attempt, resp, policy)
		if resp != nil && resp.Body != nil {
			_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<20))
			_ = resp.Body.Close()
		}

		if delay > 0 {
			if err := t.opts.sleep(req.Context(), delay); err != nil {
				return nil, err
			}
		}
	}
}

func (t *retryTransport) shouldRetry(attempt int, req *http.Request, canReplayBody bool, resp *http.Response, err error, policy RetryPolicy) bool {
	if err != nil || resp == nil {
		return false
	}
	if attempt >= policy.MaxAttempts {
		return false
	}

	switch resp.StatusCode {
	case 429:
		return canReplayBody
	case 502, 503, 504:
		if !canReplayBody {
			return false
		}
		return policy.RetryAllMethods || isIdempotentMethod(req.Method)
	default:
		return false
	}
}

func (t *retryTransport) nextDelay(attempt int, resp *http.Response, policy RetryPolicy) time.Duration {
	if resp != nil && resp.StatusCode == 429 {
		if ra := parseRetryAfter(resp.Header.Get("Retry-After"), t.opts.now()); ra > 0 {
			if policy.MaxRetryAfter > 0 && ra > policy.MaxRetryAfter {
				ra = policy.MaxRetryAfter
			}
			return ra
		}
	}

	if policy.BaseDelay <= 0 {
		return 0
	}

	exp := float64(policy.BaseDelay) * math.Pow(2, float64(attempt-1))
	delay := time.Duration(exp)
	if delay > policy.MaxDelay {
		delay = policy.MaxDelay
	}
	return policy.Jitter(delay)
}

func isIdempotentMethod(method string) bool {
	switch method {
	case http.MethodGet, http.MethodHead, http.MethodPut, http.MethodDelete, http.MethodOptions, http.MethodTrace:
		return true
	default:
		return false
	}
}

func fullJitter(d time.Duration) time.Duration {
	if d <= 0 {
		return 0
	}
	// #nosec G404 -- Retry jitter only needs inexpensive non-cryptographic randomness.
	return time.Duration(rand.Int64N(int64(d)))
}

func sleepWithContext(ctx context.Context, d time.Duration) error {
	if d <= 0 {
		return nil
	}
	timer := time.NewTimer(d)
	defer timer.Stop()
	select {
	case <-timer.C:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

type noRetryKey struct{}

func withNoRetry(ctx context.Context) context.Context {
	return context.WithValue(ctx, noRetryKey{}, true)
}

func isNoRetry(ctx context.Context) bool {
	disabled, _ := ctx.Value(noRetryKey{}).(bool)
	return disabled
}

type retryPolicyKey struct{}

func withRetryPolicy(ctx context.Context, policy RetryPolicy) context.Context {
	return context.WithValue(ctx, retryPolicyKey{}, policy)
}

func retryPolicyFromContext(ctx context.Context) (RetryPolicy, bool) {
	policy, ok := ctx.Value(retryPolicyKey{}).(RetryPolicy)
	return policy, ok
}

func sanitizeRetryPolicy(policy RetryPolicy) RetryPolicy {
	if policy.MaxAttempts <= 0 {
		policy.MaxAttempts = 1
	}
	if policy.BaseDelay < 0 {
		policy.BaseDelay = 0
	}
	if policy.MaxDelay <= 0 {
		policy.MaxDelay = policy.BaseDelay
	}
	if policy.MaxRetryAfter == 0 {
		policy.MaxRetryAfter = defaultMaxRetryAfter
	}
	if policy.Jitter == nil {
		policy.Jitter = func(d time.Duration) time.Duration { return d }
	}
	return policy
}

package v1

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"

	"github.com/juhokoskela/pipedrive-go/pipedrive"
)

type File struct {
	ID          FileID          `json:"id,omitempty"`
	Name        string          `json:"name,omitempty"`
	FileName    string          `json:"file_name,omitempty"`
	FileType    string          `json:"file_type,omitempty"`
	FileSize    int             `json:"file_size,omitempty"`
	Description string          `json:"description,omitempty"`
	URL         string          `json:"url,omitempty"`
	UserID      *UserID         `json:"user_id,omitempty"`
	DealID      *DealID         `json:"deal_id,omitempty"`
	PersonID    *PersonID       `json:"person_id,omitempty"`
	OrgID       *OrganizationID `json:"org_id,omitempty"`
	ProductID   *ProductID      `json:"product_id,omitempty"`
	ActivityID  *ActivityID     `json:"activity_id,omitempty"`
	LeadID      *LeadID         `json:"lead_id,omitempty"`
	Active      bool            `json:"active_flag,omitempty"`
	Inline      bool            `json:"inline_flag,omitempty"`
	AddTime     *DateTime       `json:"add_time,omitempty"`
	UpdateTime  *DateTime       `json:"update_time,omitempty"`
}

type FilesService struct {
	client *Client
}

type FilesOption interface {
	applyFiles(*filesOptions)
}

type filesOptions struct {
	query          url.Values
	requestOptions []pipedrive.RequestOption
}

type filesOptionFunc func(*filesOptions)

func (f filesOptionFunc) applyFiles(cfg *filesOptions) {
	f(cfg)
}

func WithFilesQuery(values url.Values) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.query = mergeQueryValues(cfg.query, values)
	})
}

func WithFilesRequestOptions(opts ...pipedrive.RequestOption) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.requestOptions = append(cfg.requestOptions, opts...)
	})
}

func newFilesOptions(opts []FilesOption) filesOptions {
	var cfg filesOptions
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		opt.applyFiles(&cfg)
	}
	return cfg
}

func (s *FilesService) List(ctx context.Context, opts ...FilesOption) ([]File, *Pagination, error) {
	cfg := newFilesOptions(opts)

	var payload struct {
		Data           []File `json:"data"`
		AdditionalData *struct {
			Pagination *Pagination `json:"pagination"`
		} `json:"additional_data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodGet, "/files", cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
		return nil, nil, err
	}
	var page *Pagination
	if payload.AdditionalData != nil {
		page = payload.AdditionalData.Pagination
	}
	return payload.Data, page, nil
}

func (s *FilesService) Get(ctx context.Context, id FileID, opts ...FilesOption) (*File, error) {
	if err := validateID(id, "file id"); err != nil {
		return nil, err
	}
	cfg := newFilesOptions(opts)
	path := fmt.Sprintf("/files/%d", id)

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodGet, path, cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

func (s *FilesService) Add(ctx context.Context, body io.Reader, contentType string, opts ...FilesOption) (*File, error) {
	cfg := newFilesOptions(opts)
	if body == nil {
		return nil, fmt.Errorf("file body is required")
	}
	if contentType == "" {
		return nil, fmt.Errorf("content type is required")
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

func (s *FilesService) AddRemoteFile(ctx context.Context, form url.Values, opts ...FilesOption) (*File, error) {
	cfg := newFilesOptions(opts)
	if len(form) == 0 {
		return nil, fmt.Errorf("form values are required")
	}

	body := strings.NewReader(form.Encode())
	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", "application/x-www-form-urlencoded"))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files/remote", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing remote file data in response")
	}
	return payload.Data, nil
}

func (s *FilesService) LinkRemoteFile(ctx context.Context, form url.Values, opts ...FilesOption) (*File, error) {
	cfg := newFilesOptions(opts)
	if len(form) == 0 {
		return nil, fmt.Errorf("form values are required")
	}

	body := strings.NewReader(form.Encode())
	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", "application/x-www-form-urlencoded"))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files/remoteLink", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing linked file data in response")
	}
	return payload.Data, nil
}

func (s *FilesService) Update(ctx context.Context, id FileID, body io.Reader, contentType string, opts ...FilesOption) (*File, error) {
	if err := validateID(id, "file id"); err != nil {
		return nil, err
	}
	cfg := newFilesOptions(opts)
	if body == nil {
		return nil, fmt.Errorf("file body is required")
	}
	if contentType == "" {
		return nil, fmt.Errorf("content type is required")
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	path := fmt.Sprintf("/files/%d", id)
	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPut, path, cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file update data in response")
	}
	return payload.Data, nil
}

func (s *FilesService) Delete(ctx context.Context, id FileID, opts ...FilesOption) (bool, error) {
	if err := validateID(id, "file id"); err != nil {
		return false, err
	}
	cfg := newFilesOptions(opts)
	path := fmt.Sprintf("/files/%d", id)

	var payload struct {
		Success *bool `json:"success"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodDelete, path, cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
		return false, err
	}
	if payload.Success == nil {
		return false, fmt.Errorf("missing file delete success in response")
	}
	return *payload.Success, nil
}

func (s *FilesService) Download(ctx context.Context, id FileID, opts ...FilesOption) ([]byte, error) {
	if err := validateID(id, "file id"); err != nil {
		return nil, err
	}
	cfg := newFilesOptions(opts)
	ctx, editors := pipedrive.ApplyRequestOptions(ctx, cfg.requestOptions...)

	resp, err := s.client.gen.DownloadFile(ctx, int(id), toRequestEditors(editors)...)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("read response: %w", err)
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return nil, errorFromResponse(resp, body)
	}
	return body, nil
}

func (s *FilesService) DownloadTo(ctx context.Context, id FileID, dst io.Writer, opts ...FilesOption) error {
	if err := validateID(id, "file id"); err != nil {
		return err
	}
	if dst == nil {
		return fmt.Errorf("download destination is required")
	}

	cfg := newFilesOptions(opts)
	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithNoResponseSizeLimit())
	ctx, editors := pipedrive.ApplyRequestOptions(ctx, reqOpts...)

	resp, err := s.client.gen.DownloadFile(ctx, int(id), toRequestEditors(editors)...)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
		if err != nil {
			return fmt.Errorf("read response: %w", err)
		}
		return errorFromResponse(resp, body)
	}
	if _, err := io.Copy(dst, resp.Body); err != nil {
		return fmt.Errorf("write download: %w", err)
	}
	return nil
}

package pipedrive

import (
	"context"
	"net/http"
)

type RequestEditorFunc func(ctx context.Context, req *http.Request) error

type RequestOption func(*requestOptions)

type requestOptions struct {
	headers map[string]string
	editors []RequestEditorFunc

	noRetry bool

	retryPolicy       *RetryPolicy
	responseSizeLimit responseSizeLimitOption
}

func WithHeader(key, value string) RequestOption {
	return func(o *requestOptions) {
		if o.headers == nil {
			o.headers = make(map[string]string)
		}
		o.headers[key] = value
	}
}

func WithRequestEditor(fn RequestEditorFunc) RequestOption {
	return func(o *requestOptions) {
		if fn == nil {
			return
		}
		o.editors = append(o.editors, fn)
	}
}

func WithNoRetry() RequestOption {
	return func(o *requestOptions) {
		o.noRetry = true
	}
}

func WithRetryPolicy(policy RetryPolicy) RequestOption {
	return func(o *requestOptions) {
		o.retryPolicy = &policy
	}
}

func WithResponseSizeLimit(limit int64) RequestOption {
	return func(o *requestOptions) {
		o.responseSizeLimit = responseSizeLimitOption{
			set:   true,
			limit: limit,
		}
	}
}

func WithNoResponseSizeLimit() RequestOption {
	return func(o *requestOptions) {
		o.responseSizeLimit = responseSizeLimitOption{
			set:       true,
			unlimited: true,
		}
	}
}

func ApplyRequestOptions(ctx context.Context, opts ...RequestOption) (context.Context, []RequestEditorFunc) {
	if ctx == nil {
		ctx = context.Background()
	}

	var o requestOptions
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		opt(&o)
	}

	if o.noRetry {
		ctx = withNoRetry(ctx)
	}
	if o.retryPolicy != nil {
		ctx = withRetryPolicy(ctx, *o.retryPolicy)
	}
	if o.responseSizeLimit.set {
		ctx = withResponseSizeLimit(ctx, o.responseSizeLimit)
	}

	editors := make([]RequestEditorFunc, 0, len(o.editors)+1)
	if len(o.headers) > 0 {
		headers := make(map[string]string, len(o.headers))
		for k, v := range o.headers {
			headers[k] = v
		}
		editors = append(editors, func(_ context.Context, req *http.Request) error {
			for k, v := range headers {
				req.Header.Set(k, v)
			}
			return nil
		})
	}
	editors = append(editors, o.editors...)

	return ctx, editors
}

package v1

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"time"

	genv1 "github.com/juhokoskela/pipedrive-go/internal/gen/v1"
	"github.com/juhokoskela/pipedrive-go/internal/multipartbody"
	"github.com/juhokoskela/pipedrive-go/pipedrive"
)

type CallLogOutcome string

const (
	CallLogOutcomeConnected     CallLogOutcome = "connected"
	CallLogOutcomeNoAnswer      CallLogOutcome = "no_answer"
	CallLogOutcomeLeftMessage   CallLogOutcome = "left_message"
	CallLogOutcomeLeftVoicemail CallLogOutcome = "left_voicemail"
	CallLogOutcomeWrongNumber   CallLogOutcome = "wrong_number"
	CallLogOutcomeBusy          CallLogOutcome = "busy"
)

type CallLog struct {
	ID             CallLogID       `json:"id"`
	ActivityID     *ActivityID     `json:"activity_id,omitempty"`
	Subject        string          `json:"subject,omitempty"`
	Duration       string          `json:"duration,omitempty"`
	Outcome        CallLogOutcome  `json:"outcome,omitempty"`
	FromPhone      string          `json:"from_phone_number,omitempty"`
	ToPhone        string          `json:"to_phone_number,omitempty"`
	StartTime      *DateTime       `json:"start_time,omitempty"`
	EndTime        *DateTime       `json:"end_time,omitempty"`
	PersonID       *PersonID       `json:"person_id,omitempty"`
	OrganizationID *OrganizationID `json:"org_id,omitempty"`
	DealID         *DealID         `json:"deal_id,omitempty"`
	LeadID         *LeadID         `json:"lead_id,omitempty"`
	UserID         *UserID         `json:"user_id,omitempty"`
	CompanyID      *int            `json:"company_id,omitempty"`
	HasRecording   bool            `json:"has_recording,omitempty"`
	Note           string          `json:"note,omitempty"`
}

type CallLogsPagination struct {
	Start                 int  `json:"start,omitempty"`
	Limit                 int  `json:"limit,omitempty"`
	MoreItemsInCollection bool `json:"more_items_in_collection,omitempty"`
	NextStart             *int `json:"next_start,omitempty"`
}

type CallLogsService struct {
	client *Client
}

type ListCallLogsOption interface {
	applyListCallLogs(*listCallLogsOptions)
}

type CreateCallLogOption interface {
	applyCreateCallLog(*createCallLogOptions)
}

type GetCallLogOption interface {
	applyGetCallLog(*getCallLogOptions)
}

type DeleteCallLogOption interface {
	applyDeleteCallLog(*deleteCallLogOptions)
}

type AddCallLogRecordingOption interface {
	applyAddCallLogRecording(*addCallLogRecordingOptions)
}

type CallLogsRequestOption interface {
	ListCallLogsOption
	CreateCallLogOption
	GetCallLogOption
	DeleteCallLogOption
	AddCallLogRecordingOption
}

type CallLogOption interface {
	CreateCallLogOption
}

type listCallLogsOptions struct {
	params         genv1.GetUserCallLogsParams
	requestOptions []pipedrive.RequestOption
}

type createCallLogOptions struct {
	payload        callLogPayload
	requestOptions []pipedrive.RequestOption
}

type getCallLogOptions struct {
	requestOptions []pipedrive.RequestOption
}

type deleteCallLogOptions struct {
	requestOptions []pipedrive.RequestOption
}

type addCallLogRecordingOptions struct {
	requestOptions []pipedrive.RequestOption
}

type callLogPayload struct {
	userID     *UserID
	activityID *ActivityID
	subject    *string
	duration   *string
	outcome    *CallLogOutcome
	fromPhone  *string
	toPhone    *string
	startTime  *time.Time
	endTime    *time.Time
	personID   *PersonID
	orgID      *OrganizationID
	dealID     *DealID
	leadID     *LeadID
	note       *string
}

type callLogsRequestOptions struct {
	requestOptions []pipedrive.RequestOption
}

func (o callLogsRequestOptions) applyListCallLogs(cfg *listCallLogsOptions) {
	cfg.requestOptions = append(cfg.requestOptions, o.requestOptions...)
}

func (o callLogsRequestOptions) applyCreateCallLog(cfg *createCallLogOptions) {
	cfg.requestOptions = append(cfg.requestOptions, o.requestOptions...)
}

func (o callLogsRequestOptions) applyGetCallLog(cfg *getCallLogOptions) {
	cfg.requestOptions = append(cfg.requestOptions, o.requestOptions...)
}

func (o callLogsRequestOptions) applyDeleteCallLog(cfg *deleteCallLogOptions) {
	cfg.requestOptions = append(cfg.requestOptions, o.requestOptions...)
}

func (o callLogsRequestOptions) applyAddCallLogRecording(cfg *addCallLogRecordingOptions) {
	cfg.requestOptions = append(cfg.requestOptions, o.requestOptions...)
}

type listCallLogsOptionFunc func(*listCallLogsOptions)

func (f listCallLogsOptionFunc) applyListCallLogs(cfg *listCallLogsOptions) {
	f(cfg)
}

type callLogFieldOption func(*callLogPayload)

func (f callLogFieldOption) applyCreateCallLog(cfg *createCallLogOptions) {
	f(&cfg.payload)
}

func WithCallLogsRequestOptions(opts ...pipedrive.RequestOption) CallLogsRequestOption {
	return callLogsRequestOptions{requestOptions: opts}
}

func WithCallLogsStart(start int) ListCallLogsOption {
	return listCallLogsOptionFunc(func(cfg *listCallLogsOptions) {
		cfg.params.Start = &start
	})
}

func WithCallLogsLimit(limit int) ListCallLogsOption {
	return listCallLogsOptionFunc(func(cfg *listCallLogsOptions) {
		cfg.params.Limit = &limit
	})
}

func WithCallLogUserID(id UserID) CallLogOption {
	return callLogFieldOption(func(cfg *callLogPayload) {
		cfg.userID = &id
	})
}

func WithCallLogActivityID(id ActivityID) CallLogOption {
	return callLogFieldOption(func(cfg *callLogPayload) {
		cfg.activityID = &id
	})
}

func WithCallLogSubject(subject string) CallLogOption {
	return callLogFieldOption(func(cfg *callLogPayload) {
		cfg.subject = &subject
	})
}

func WithCallLogDuration(duration string) CallLogOption {
	return callLogFieldOption(func(cfg *callLogPayload) {
		cfg.duration = &duration
	})
}

func WithCallLogOutcome(outcome CallLogOutcome) CallLogOption {
	return callLogFieldOption(func(cfg *callLogPayload) {
		cfg.outcome = &outcome
	})
}

func WithCallLogFromPhoneNumber(number string) CallLogOption {
	return callLogFieldOption(func(cfg *callLogPayload) {
