	}
}

func TestApplyRequestOptions_WithBodyReplacer(t *testing.T) {
	t.Parallel()

	replacements := 0
	ctx, editors := ApplyRequestOptions(context.Background(), WithBodyReplacer(func() (io.Reader, error) {
		replacements++
		return strings.NewReader("fresh-body"), nil
	}))
	if len(editors) != 1 {
		t.Fatalf("expected 1 editor, got %d", len(editors))
	}

	req, _ := http.NewRequestWithContext(ctx, http.MethodPost, "https://example.test", strings.NewReader("original-body"))
	if err := editors[0](ctx, req); err != nil {
		t.Fatalf("editor error: %v", err)
	}

	body, err := io.ReadAll(req.Body)
	if err != nil {
		t.Fatalf("read replaced body: %v", err)
	}
	if string(body) != "fresh-body" {
		t.Fatalf("expected body to be replaced, got %q", body)
	}
	if req.ContentLength != -1 {
		t.Fatalf("expected unknown content length, got %d", req.ContentLength)
	}
	if req.GetBody == nil {
		t.Fatalf("expected GetBody to be set so the request is replayable")
	}

	replayed, err := req.GetBody()
	if err != nil {
		t.Fatalf("GetBody error: %v", err)
	}
	defer replayed.Close()
	reread, err := io.ReadAll(replayed)
	if err != nil {
		t.Fatalf("read replayed body: %v", err)
	}
	if string(reread) != "fresh-body" {
		t.Fatalf("expected replayed body to be reproducible, got %q", reread)
	}
}

func TestApplyRequestOptions_WithBodyReplacer_ReturnsReplacerError(t *testing.T) {
	t.Parallel()

	boom := errors.New("cannot re-open source")
	ctx, editors := ApplyRequestOptions(context.Background(), WithBodyReplacer(func() (io.Reader, error) {
		return nil, boom
	}))

	req, _ := http.NewRequestWithContext(ctx, http.MethodPost, "https://example.test", strings.NewReader("body"))
	if err := editors[0](ctx, req); !errors.Is(err, boom) {
		t.Fatalf("expected replacer error, got %v", err)
	}
}

func TestApplyRequestOptions_WithBodyReplacer_RejectsNilReader(t *testing.T) {
	t.Parallel()

	ctx, editors := ApplyRequestOptions(context.Background(), WithBodyReplacer(func() (io.Reader, error) {
		return nil, nil
	}))

	req, _ := http.NewRequestWithContext(ctx, http.MethodPost, "https://example.test", strings.NewReader("body"))
	if err := editors[0](ctx, req); err == nil {
		t.Fatalf("expected error for nil replacer reader")
	}
}

