func TestFilesService_AddFile(t *testing.T) {
	t.Parallel()

	content := []byte("report-bytes")
	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}

		mediaType, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
		if err != nil {
			t.Fatalf("parse content type: %v", err)
		}
		if mediaType != "multipart/form-data" {
			t.Fatalf("unexpected media type: %s", mediaType)
		}

		reader := multipart.NewReader(r.Body, params["boundary"])
		var filePart *multipart.Part
		fields := map[string]string{}
		for {
			part, err := reader.NextPart()
			if err == io.EOF {
				break
			}
			if err != nil {
				t.Fatalf("read part: %v", err)
			}
			if part.FileName() != "" {
				filePart = part
				continue
			}
			value, err := io.ReadAll(part)
			if err != nil {
				t.Fatalf("read field %q: %v", part.FormName(), err)
			}
			fields[part.FormName()] = string(value)
		}
		if filePart == nil {
			t.Fatalf("missing file part")
		}
		if filePart.FormName() != "file" {
			t.Fatalf("unexpected file form name: %s", filePart.FormName())
		}
		if filePart.FileName() != "report.pdf" {
			t.Fatalf("unexpected file name: %s", filePart.FileName())
		}
		payload, err := io.ReadAll(filePart)
		if err != nil {
			t.Fatalf("read file part: %v", err)
		}
		if !bytes.Equal(payload, content) {
			t.Fatalf("unexpected file content: %q", payload)
		}

		want := map[string]string{
			"deal_id":     "1",
			"person_id":   "2",
			"org_id":      "3",
			"product_id":  "4",
			"activity_id": "5",
			"lead_id":     "lead-uuid",
			"project_id":  "7",
		}
		if len(fields) != len(want) {
			t.Fatalf("unexpected fields: %#v", fields)
		}
		for key, value := range want {
			if fields[key] != value {
				t.Fatalf("unexpected field %s: %q", key, fields[key])
			}
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"report.pdf"}}`))
	})

	file, err := client.Files.AddFile(
		context.Background(),
		"report.pdf",
		bytes.NewReader(content),
		WithFileDealID(DealID(1)),
		WithFilePersonID(PersonID(2)),
		WithFileOrgID(OrganizationID(3)),
		WithFileProductID(ProductID(4)),
		WithFileActivityID(ActivityID(5)),
		WithFileLeadID(LeadID("lead-uuid")),
		WithFileProjectID(ProjectID(7)),
	)
	if err != nil {
		t.Fatalf("AddFile error: %v", err)
	}
	if file.ID != 12 || file.Name != "report.pdf" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

