package v1

import (
	"context"
	"fmt"
	"io"
	"mime"
	"mime/multipart"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/juhokoskela/pipedrive-go/pipedrive"
)

func TestRepro_RealFile_429Retry(t *testing.T) {
	data := strings.Repeat("x", 4096)
	path := filepath.Join(t.TempDir(), "invoice.pdf")
	if err := os.WriteFile(path, []byte(data), 0o644); err != nil {
		t.Fatal(err)
	}

	var (
		mu     sync.Mutex
		calls  int
		bodies [][]byte
	)
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		b, _ := io.ReadAll(r.Body)
		mu.Lock()
		calls++
		bodies = append(bodies, b)
		mu.Unlock()
		if calls == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":1}}`))
	}))
	t.Cleanup(srv.Close)

	policy := pipedrive.DefaultRetryPolicy()
	policy.BaseDelay = time.Millisecond
	policy.MaxDelay = time.Millisecond
	cfg := pipedrive.Config{BaseURL: srv.URL, RetryPolicy: &policy}
	client, err := NewClient(cfg)
	if err != nil {
		t.Fatal(err)
	}

	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()

	file, err := client.Files.AddFile(context.Background(), "invoice.pdf", f, WithFileDealID(DealID(9)))
	if err != nil {
		t.Fatalf("AddFile: %v", err)
	}
	if file.ID != 1 {
		t.Fatalf("unexpected file: %#v", file)
	}

	mu.Lock()
	defer mu.Unlock()
	if calls != 2 {
		t.Fatalf("expected 2 attempts, got %d", calls)
	}
	for i, b := range bodies {
		if !strings.Contains(string(b), data) {
			t.Fatalf("attempt %d missing full content", i+1)
		}
	}
	// parse second body, verify multipart + fields
	mediaType, params, _ := mime.ParseMediaType("multipart/form-data; boundary=" + paramsBoundary(bodies[1]))
	_ = mediaType
	_ = params
}

func paramsBoundary(body []byte) string {
	// body starts with "--boundary"
	i := strings.Index(string(body), "\r\n")
	line := string(body[:i])
	return strings.TrimPrefix(line, "--")
}

func TestRepro_RawAdd_WithReplacer_Retries(t *testing.T) {
	data := []byte("streamed-multipart-payload")

	var (
		mu    sync.Mutex
		calls int
	)
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = io.ReadAll(r.Body)
		mu.Lock()
		calls++
		mu.Unlock()
		if calls == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":2}}`))
	}))
	t.Cleanup(srv.Close)

	policy := pipedrive.DefaultRetryPolicy()
	policy.BaseDelay = time.Millisecond
	policy.MaxDelay = time.Millisecond
	cfg := pipedrive.Config{BaseURL: srv.URL, RetryPolicy: &policy}
	client, err := NewClient(cfg)
	if err != nil {
		t.Fatal(err)
	}

	ct := "multipart/form-data; boundary=abc"
	_, err = client.Files.Add(context.Background(), &v1EOFReader{data: data}, ct,
		WithFilesRequestOptions(
			pipedrive.WithBodyReplacer(func() (io.Reader, error) {
				return strings.NewReader(fmt.Sprintf("replayed:%s", data)), nil
			}),
		),
	)
	if err != nil {
		t.Fatalf("Add: %v", err)
	}
	mu.Lock()
	defer mu.Unlock()
	if calls != 2 {
		t.Fatalf("expected 2 attempts, got %d", calls)
	}
}

